<script setup lang="ts">import {computed,onMounted,onUnmounted,ref,watch} from 'vue';import {Upload,RefreshCw,CheckCircle2,AlertTriangle} from 'lucide-vue-next';import {useResearch} from '../stores/research';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {createBatch,publishBatch,retryBatch} from '../api/calibrations';import DataTable from './common/DataTable.vue';import StatusBadge from './common/StatusBadge.vue';import {BatchStatus,ItemStatus} from '../constants/enums';import {number,percent,time} from '../utils/format';
const props=defineProps<{libraryId:number}>();const s=useResearch(),auth=useAuth(),a=useAction(),fileInput=ref<HTMLInputElement>(),fileName=ref(''),parsed=ref<null|{title:string;endmembers:{code:string;name:string;spectrum:number[]}[]}>(null),uploadError=ref(''),selected=ref(0),panelError=ref(''),success=ref('');
const batches=computed(()=>s.batches);const batch=computed(()=>batches.value.find(b=>b.id===selected.value)||batches.value[0]);
const canWrite=computed(()=>auth.user?.role==='admin'||auth.user?.role==='analyst');
watch(()=>props.libraryId,()=>{selected.value=0;parsed.value=null;fileName.value='';uploadError.value=''});
function onFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;fileName.value=file.name;uploadError.value='';parsed.value=null;const reader=new FileReader();reader.onload=()=>{try{const body=JSON.parse(String(reader.result));const list=Array.isArray(body.endmembers)?body.endmembers:Array.isArray(body)?body:null;if(!list)throw new Error('文件需包含 endmembers 数组，或直接为端元数组');parsed.value={title:String(body.title||file.name.replace(/\.json$/i,'')),endmembers:list.map((e:{code:string;name?:string;spectrum:number[]})=>({code:String(e.code||''),name:String(e.name||e.code||''),spectrum:(e.spectrum||[]).map(Number)}))};}catch(e){uploadError.value='复测谱解析失败：'+(e as Error).message}};reader.readAsText(file)}
function upload(){if(!parsed.value)return;a.execute(async()=>{const created=await createBatch(props.libraryId,{title:parsed.value!.title,endmembers:parsed.value!.endmembers});selected.value=created.id;parsed.value=null;fileName.value='';if(fileInput.value)fileInput.value.value='';await s.loadBatches(props.libraryId);await s.refresh();success.value=created.status==='failed'?'批次已提交，但端元未通过可辨识性检查，未启动重算。':'批次已提交，worker 正在沿用各研究样本与扰动参数重算。'})}
function publish(){if(!batch.value)return;panelError.value='';success.value='';a.execute(async()=>{try{await publishBatch(batch.value!.id);success.value='全部研究重算成功，已原子切换现行端元与结果。';}finally{await s.loadBatches(props.libraryId);await s.refresh()}})}
function retry(){if(!batch.value)return;a.execute(async()=>{await retryBatch(batch.value!.id);await s.loadBatches(props.libraryId)})}
function refresh(){a.execute(async()=>{await s.loadBatches(props.libraryId)})}
let timer:ReturnType<typeof setInterval>|undefined;
onMounted(()=>{timer=setInterval(()=>{if(batches.value.some(b=>b.status==='computing'))s.loadBatches(props.libraryId)},2000)});
onUnmounted(()=>{if(timer)clearInterval(timer)});
const statusText=(x:string)=>BatchStatus[x as keyof typeof BatchStatus]||x;const itemText=(x:string)=>ItemStatus[x as keyof typeof ItemStatus]||x;
const maxDelta=(b:typeof batch.value)=>b?.items.reduce((m,i)=>Math.max(m,i.changes?.max_abs_delta??0),0)??0;
</script>
<template><section class="calibration-panel"><div class="section-top"><div><span class="eyebrow">ENDMEMBER RECALIBRATION / 批次</span><h2>复测谱与现行校准</h2><p class="caption">按批次上传各端元复测谱（JSON）。系统沿用该库每个既有研究的样本、sigma、重复数与种子重算，全部成功后才能一起切换；失败保留 v{{ s.libraries.find(l=>l.id===libraryId)?.calibration_version }} 现行校准并可恢复。</p></div><div class="panel-actions"><button class="outline" :disabled="a.busy.value" @click="refresh"><RefreshCw :size="14"/>刷新批次</button></div></div>
<div v-if="canWrite" class="upload-row"><label class="file-field">复测谱文件<input ref="fileInput" aria-label="复测谱文件" type="file" accept="application/json,.json" @change="onFile"/></label><label v-if="parsed" class="title-field">批次标题<input aria-label="批次标题" v-model="parsed.title" maxlength="160"/></label><button class="primary" :disabled="!parsed||a.busy.value" @click="upload"><Upload :size="15"/>上传并重算</button></div>
<p v-if="uploadError" class="notice">{{uploadError}}</p><p v-if="parsed" class="caption">{{fileName}} · {{parsed.endmembers.length}} 个端元 · 波段与前缀校验在服务端执行</p>
<div v-if="a.error.value" class="notice">{{a.error.value}}</div><div v-if="panelError" class="notice">{{panelError}}</div><div v-if="success" class="notice success-note"><CheckCircle2 :size="14"/>{{success}}</div>
<div v-if="!batches.length" class="empty">尚无复测批次。上传复测端元谱后，系统会重算该库全部研究，再决定是否切换。</div>
<template v-else><div class="batch-list"><button v-for="b in batches" :key="b.id" :class="['batch-card',selected===b.id?'active':'']" @click="selected=b.id"><span class="eyebrow">BATCH-{{b.id}} · v{{b.base_version}}→{{b.version??b.base_version+1}}</span><b>{{b.title||'未命名复测批次'}}</b><span :class="['batch-state',b.status]">{{statusText(b.status)}}</span><span class="batch-progress">{{b.item_completed}}/{{b.item_total}} 完成 · {{percent(b.progress)}}</span></button></div>
<article v-if="batch" class="batch-detail"><header><div><h3>{{batch.title||'未命名复测批次'}}</h3><p class="caption">基于 v{{batch.base_version}} · {{batch.created_by}} · {{time(batch.created_at)}}<template v-if="batch.published_at"> · 切换于 {{time(batch.published_at)}}</template></p></div><StatusBadge :status="batch.status"/></header>
<div class="progress-track" role="progressbar" :aria-valuenow="batch.progress_percent" aria-valuemin="0" aria-valuemax="100"><i :style="{width:batch.progress_percent+'%'}" :class="batch.status"/></div>
<p class="caption">{{batch.item_completed}} / {{batch.item_total}} 研究重算完成<template v-if="batch.item_failed"> · {{batch.item_failed}} 失败</template> · 最大配比变化 {{batch.item_total?number(maxDelta(batch),4):'—'}}</p>
<p v-if="batch.stale" class="notice">此批基于 v{{batch.base_version}}，现行校准已是 v{{batch.current_calibration_version}}。迟到的完成不会回退现行校准；需重新上传复测谱。</p><div v-if="batch.failure_reason" class="failure-box"><AlertTriangle :size="15"/><div><b>失败原因</b><p>{{batch.failure_reason}}</p><div v-if="batch.failure_items.length"><span v-for="f in batch.failure_items" :key="f.run_id">#{{f.run_id}} {{f.run_name}} — {{f.reason}}</span></div></div></div>
<div class="batch-actions"><button v-if="canWrite&&batch.status==='ready'" class="primary" :disabled="a.busy.value" @click="publish"><CheckCircle2 :size="15"/>全部成功，切换现行校准</button><button v-if="canWrite&&(batch.status==='failed'||(batch.status==='computing'&&batch.item_failed))" class="outline" :disabled="a.busy.value" @click="retry">重试失败研究</button><span v-if="batch.status==='published'" class="published-note">现行端元已是 v{{batch.version}}；新结果待另行审阅，原获批导出仍按原校准版本保留。</span><span v-else-if="batch.status==='superseded'" class="published-note">此批未切换，现行校准未被改写。</span></div>
<DataTable :head="['研究','状态','来源复用','最大配比变化','平均绝对变化','失败原因']"><tr v-for="i in batch.items" :key="i.id"><td>#{{i.run_id}} / {{i.run_name}}</td><td><span :class="['item-state',i.status]">{{itemText(i.status)}}</span></td><td>{{i.reused?'来源一致，复用结果':'重新计算'}}</td><td>{{i.changes?.max_abs_delta==null?'—':number(i.changes.max_abs_delta,4)}}</td><td>{{i.changes?.mean_abs_delta==null?'—':number(i.changes.mean_abs_delta,4)}}</td><td class="failure-cell">{{i.failure_reason||'—'}}</td></tr></DataTable>
<details v-if="batch.items.some(i=>i.changes?.samples?.length)" class="change-detail"><summary>逐样本配比变化</summary><div v-for="i in batch.items.filter(x=>x.changes?.samples?.length)" :key="i.id"><h4>#{{i.run_id}} {{i.run_name}}<small v-if="i.changes.removed_codes.length"> · 移除端元 {{i.changes.removed_codes.join('、')}}</small><small v-if="i.changes.added_codes.length"> · 新增端元 {{i.changes.added_codes.join('、')}}</small></h4><DataTable :head="['样本',...i.changes.endmembers.map(e=>e.code),'最大绝对变化']"><tr v-for="row in i.changes.samples" :key="row.code"><td class="mono">{{row.code}}</td><td v-for="e in i.changes.endmembers" :key="e.code">{{number(row.before[e.code]??0,4)}} → <b>{{number(row.after[e.code]??0,4)}}</b><small> ({{(row.delta[e.code]??0)>=0?'+':''}}{{number(row.delta[e.code]??0,4)}})</small></td><td>{{number(row.max_abs_delta,4)}}</td></tr></DataTable></div></details>
</article></template></section></template>
